begin;

create temporary table phase_39_17d_expected_evidence (
  booking_id uuid primary key,
  expected_booking_reference text not null,
  expected_show_date date not null,
  expected_guest_count integer not null,
  expected_section text not null,
  expected_total_amount numeric(12, 2) not null,
  expected_amount_paid numeric(12, 2) not null,
  expected_booking_status text not null,
  source_row_number integer not null,
  source_row_fingerprint text not null unique,
  source_payment_amount numeric(12, 2) not null,
  source_ticket_amount numeric(12, 2) not null,
  full_card_amount numeric(12, 2) not null,
  pre_paid_card_amount numeric(12, 2) not null,
  pre_paid_eft_amount numeric(12, 2) not null,
  full_eft_amount numeric(12, 2) not null,
  complimentary boolean not null,
  complimentary_amount numeric(12, 2) not null,
  ticket_gratuity_amount numeric(12, 2) not null,
  bar_tab_paid_amount numeric(12, 2) not null,
  bar_gratuity_amount numeric(12, 2) not null,
  halaal_meals_amount numeric(12, 2) not null,
  kosher_meals_amount numeric(12, 2) not null,
  classification_reason text not null,
  match_basis text[] not null
) on commit drop;



do $$
declare
  global_booking_count integer;
  september_booking_count integer;
  exact_target_count integer;
begin
  select count(*) into global_booking_count from public.bookings;
  if global_booking_count <> 1388 then
    raise exception 'Phase 39.17D booking snapshot changed: expected 1388, found %', global_booking_count;
  end if;

  select count(*) into september_booking_count
  from public.bookings b
  join public.shows s on s.id = b.show_id
  where s.venue = 'johannesburg'
    and s.date between date '2026-09-01' and date '2026-09-30';
  if september_booking_count <> 1238 then
    raise exception 'Phase 39.17D September snapshot changed: expected 1238, found %', september_booking_count;
  end if;

  select count(*) into exact_target_count
  from phase_39_17d_expected_evidence expected
  join public.bookings b on b.id = expected.booking_id
  join public.shows s on s.id = b.show_id
  where b.booking_reference = expected.expected_booking_reference
    and s.venue = 'johannesburg'
    and s.date = expected.expected_show_date
    and b.guest_count = expected.expected_guest_count
    and b.section = expected.expected_section
    and b.total_amount = expected.expected_total_amount
    and b.amount_paid = expected.expected_amount_paid
    and b.booking_status::text = expected.expected_booking_status
    and b.archived_at is null;

  if exact_target_count <> 1066 then
    raise exception 'Phase 39.17D target state changed: expected 1066 exact rows, found %', exact_target_count;
  end if;

  if exists (
    select 1
    from public.legacy_booking_payment_evidence existing
    join phase_39_17d_expected_evidence expected
      on existing.booking_id = expected.booking_id
    where existing.source_checksum <> '49455bdbd06156c8b3a5a61f19483903229ac8820b4321f8ad992b4d55244e89'
       or existing.source_row_number <> expected.source_row_number
       or existing.source_row_fingerprint <> expected.source_row_fingerprint
  ) then
    raise exception 'Phase 39.17D found conflicting existing evidence';
  end if;
end
$$;

  booking_id,
  source_system,
  source_document,
  source_checksum,
  source_row_number,
  source_row_fingerprint,
  source_payment_amount,
  source_ticket_amount,
  full_card_amount,
  pre_paid_card_amount,
  pre_paid_eft_amount,
  full_eft_amount,
  complimentary,
  complimentary_amount,
  ticket_gratuity_amount,
  bar_tab_paid_amount,
  bar_gratuity_amount,
  halaal_meals_amount,
  kosher_meals_amount,
  classification_reason,
  match_basis,
  reconciliation_note
)
select
  booking_id,
  'dineplan',
  'Dineplan Bookings September 2026.xlsx',
  '49455bdbd06156c8b3a5a61f19483903229ac8820b4321f8ad992b4d55244e89',
  source_row_number,
  source_row_fingerprint,
  source_payment_amount,
  source_ticket_amount,
  full_card_amount,
  pre_paid_card_amount,
  pre_paid_eft_amount,
  full_eft_amount,
  complimentary,
  complimentary_amount,
  ticket_gratuity_amount,
  bar_tab_paid_amount,
  bar_gratuity_amount,
  halaal_meals_amount,
  kosher_meals_amount,
  classification_reason,
  match_basis,
  'Phase 39.17D consolidated September Dineplan recovery'
from phase_39_17d_expected_evidence
on conflict (booking_id) do nothing;

do $$
declare
  verified_count integer;
begin
  select count(*) into verified_count
  from phase_39_17d_expected_evidence expected
  join public.legacy_booking_payment_evidence actual
    on actual.booking_id = expected.booking_id
   and actual.source_checksum = '49455bdbd06156c8b3a5a61f19483903229ac8820b4321f8ad992b4d55244e89'
   and actual.source_row_number = expected.source_row_number
   and actual.source_row_fingerprint = expected.source_row_fingerprint
   and actual.source_payment_amount = expected.source_payment_amount
   and actual.source_ticket_amount = expected.source_ticket_amount
   and actual.full_card_amount = expected.full_card_amount
   and actual.pre_paid_card_amount = expected.pre_paid_card_amount
   and actual.pre_paid_eft_amount = expected.pre_paid_eft_amount
   and actual.full_eft_amount = expected.full_eft_amount
   and actual.complimentary = expected.complimentary
   and actual.complimentary_amount = expected.complimentary_amount
   and actual.ticket_gratuity_amount = expected.ticket_gratuity_amount
   and actual.bar_tab_paid_amount = expected.bar_tab_paid_amount
   and actual.bar_gratuity_amount = expected.bar_gratuity_amount
   and actual.halaal_meals_amount = expected.halaal_meals_amount
   and actual.kosher_meals_amount = expected.kosher_meals_amount
   and actual.classification_reason = expected.classification_reason;

  if verified_count <> 1066 then
    raise exception 'Phase 39.17D evidence verification failed: expected 1066, found %', verified_count;
  end if;
end
$$;

commit;
